example.programlisting:
using System;
using System.Collections.Generic;
using Rexx.Net;

var shop = new Shop();
using var rexx = RexxInterpreter.Create(new RexxOptions { StreamPrefixes = false });
rexx.Local["SHOP"] = shop;                     // .shop in the Rexx code
rexx.Run(
    "do item over 'apple pear fig'~makeArray(' ')\n" +
    "  .shop~Add(item, item~length * 10)\n" +
    "end\n" +
    "say .shop~Count 'items,' .shop~Total 'cents'");
var discount = rexx.Compile("discount",          // a rule, kept in Rexx
    "use arg total\n" +
    "if total > 100 then return total * 0.9\n" +
    "return total");
foreach (var total in new[] { 50, 120 })
    Console.WriteLine(FormattableString.Invariant($"{total} -> {discount.Call<decimal>(total)}"));

public class Shop
{
    readonly Dictionary<string, int> items = new();
    public void Add(string name, int cents) => items[name] = cents;
    public int Count => items.Count;
    public int Total { get { int t = 0; foreach (var c in items.Values) t += c; return t; } }
}

using System;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
var pkg = rexx.LoadPackage("account.cls",
    "::class Account public\n" +
    "::attribute balance get\n" +
    "::method init; expose balance; use arg balance = 0\n" +
    "::method deposit; expose balance; use arg n; balance += n; return self\n");
RexxClass account = pkg.FindClass("Account")!;
dynamic a = account.New(10)!;
a.deposit(5).deposit(2.5);
Console.WriteLine(FormattableString.Invariant($"{a.balance} {(decimal)a.balance * 2}"));
RexxObject b = account.New()!;
b.Send("deposit", 100);
Console.WriteLine(b.Send<int>("balance") + 1);

using System;
using System.IO;
using Rexx.Net;

using var rexx = RexxInterpreter.Create();
var log = new StringWriter();
rexx.Output = log;
rexx.Input = new StringReader("Ann\n");
rexx.Run("say 'Name?'; pull name; say 'Hello,' name");
rexx.Output = null; rexx.Input = null;
foreach (var line in log.ToString().Split('\n', StringSplitOptions.RemoveEmptyEntries))
    Console.WriteLine($"[log] {line.TrimEnd()}");

using System;
using System.Collections.Generic;
using Rexx.Net;

var doc = new List<string>();
using var rexx = RexxInterpreter.Create(new RexxOptions { InitialAddress = "EDITOR" });
rexx.AddCommandEnvironment("EDITOR", cmd =>
{
    var words = cmd.Command.Split(' ', 2);
    switch (words[0].ToUpperInvariant())
    {
        case "INSERT": doc.Add(words.Length > 1 ? words[1] : ""); return 0;
        case "LINES": cmd["LINES"] = doc.Count; return 0;
        default: throw new RexxCommandException(1, "unknown command " + words[0]);
    }
});
rexx.Run(
    "'insert first line'\n" +
    "'insert second line'\n" +
    "'lines'; say 'lines:' lines\n" +
    "'frobnicate'; say 'rc:' rc");
Console.WriteLine(string.Join(" / ", doc));
